"""Reopen the saved Master and rebind every visible item to verified subsystem placements."""
import gzip,json
from pathlib import Path
from run_native import rpc
ROOT=Path(__file__).resolve().parents[1];target=json.loads((ROOT/'manifests/whole-robot-integration-target.json').read_text());model=json.loads(gzip.decompress((ROOT/target['reference_model']).read_bytes()));mapping=json.loads((ROOT/'manifests/whole-native-component-map-candidate.json').read_text())['parts'];inventory=json.loads((ROOT/'audits/current-master-assembly-refresh.json').read_text());assert inventory['passed'];names=set(inventory['instances']);expected={p['name']:{k:p.get(k)for k in ['name','mesh','leg','group']}for p in model['parts']if p['name']in names};leg=json.loads((ROOT/'audits/current-native-installed-all.json').read_text())['instances'];body=json.loads((ROOT/'audits/current-body-reference-binding.json').read_text())['parts']
script=(ROOT/'source/native_documents.py').read_text()+'\nimport adsk.core as core,adsk.fusion as fusion,json,time\n'+(ROOT/'source/current_master_inspection.py').read_text()+'''
def run(_context:str):
 app=core.Application.get();doc=authoring_document(app,'master');doc.activate();assert doc.dataFile.isComplete and not doc.isModified;file=doc.dataFile;version=file.versionNumber;tick=time.monotonic();d=fusion.Design.cast(app.activeProduct);before,_=inspect_current_master(d,EXPECTED,CUSTOM,LEG_ROWS,BODY_ROWS);parameters={p.name:p.expression for p in d.userParameters};assert doc.close(False);doc=app.documents.open(file,True);assert doc and doc.dataFile.versionNumber==version and doc.dataFile.isComplete and not doc.isModified;d=fusion.Design.cast(app.activeProduct);after,_=inspect_current_master(d,EXPECTED,CUSTOM,LEG_ROWS,BODY_ROWS);assert before['subsystems']==after['subsystems'];assert before['instances']==after['instances'];assert parameters=={p.name:p.expression for p in d.userParameters};print(json.dumps({'passed':True,'saved_master_version':version,'reopened':True,'complete':doc.dataFile.isComplete,'modified':doc.isModified,'subsystems':after['subsystems'],'model_items':after['model_items'],'solid_bodies':after['solid_bodies'],'parameters':parameters,'elapsed_seconds':time.monotonic()-tick,'scope':'Saved native Master reopened; all684 actual item identities,703solid bodies, subsystem versions, native transforms and identity-preserving vertex placements remain unchanged.'}))
'''
for key,value in [('EXPECTED',expected),('CUSTOM',list(mapping)),('LEG_ROWS',leg),('BODY_ROWS',body)]:script=script.replace(key,repr(value))
reply=rpc(script,'current-native-master-saved-reopen',timeout=1200);assert reply[0]['success'],reply;record=json.loads(reply[0]['message']);(ROOT/'audits/current-native-master-saved-reopen.json').write_text(json.dumps(record,indent=2));print({k:v for k,v in record.items()if k!='parameters'})
